export function createScene(engine, canvas, BABYLON) {
  console.clear();

  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.2, 0.3, 0.25, 1.0);
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 3, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.0, 0.7, 0));
  camera.alpha = 1.571;
  camera.beta = 1.473;
  camera.radius = 3;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 0;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.lowerRadiusLimit = 2;
  camera.upperRadiusLimit = 5;
  camera.lowerBetaLimit = 1.473;
  camera.upperBetaLimit = 1.473;
  camera.lowerAlphaLimit = 1.571;
  camera.upperAlphaLimit = 1.571;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 1;
  var dirLight = new BABYLON.DirectionalLight("dir", new BABYLON.Vector3(-1, -2, -1), scene);
  dirLight.position = new BABYLON.Vector3(10, 20, 10);

  // Liquid Shader
  BABYLON.Effect.ShadersStore["liquidVertexShader"] = `
        precision highp float;
        attribute vec3 position;
        attribute vec3 normal;
        uniform mat4 world;
        uniform mat4 worldViewProjection;
        varying vec3 vPositionW;
        varying vec3 vLocalPos;
        void main(void) {
            vLocalPos = position;
            vPositionW = vec3(world * vec4(position, 1.0));
            gl_Position = worldViewProjection * vec4(position, 1.0);
        }
    `;

  BABYLON.Effect.ShadersStore["liquidFragmentShader"] = `
        precision highp float;
        varying vec3 vPositionW;
        varying vec3 vLocalPos;
        uniform vec3 worldPos;
        uniform vec3 sideColor;
        uniform vec3 topColor;
        uniform float fillLevel;
        uniform vec2 wobble;
        uniform float time;
        uniform float rippleStrength;

        void main(void) {
            vec3 worldRelPos = vPositionW - worldPos;
            
            // 수평 흔들림 (기울기)
            float surfaceCenter = (worldRelPos.x * wobble.x) + (worldRelPos.z * wobble.y);
            
            // 2D 리플 연산 (X, Z축 복합 사인파로 훨씬 액체스럽게 변경)
            float wave = sin(vLocalPos.x * 12.0 + time * 4.0) * 0.5;
            wave += cos(vLocalPos.z * 10.0 + time * 3.5) * 0.5;
            float ripple = wave * rippleStrength;
            
            // 최종 컷오프 (리플의 영향력을 높임)
            float cutOff = worldRelPos.y + surfaceCenter - ripple;

            if (cutOff > fillLevel) discard;

            vec3 color = gl_FrontFacing ? sideColor : topColor;
            
            // 수면 반사광 페이크 (가독성 향상)
            if(!gl_FrontFacing) color += 0.05;

            gl_FragColor = vec4(color, 1.0);
        }
    `;

  const liquidMaterial = new BABYLON.ShaderMaterial(
    "liquidMat",
    scene,
    {
      vertex: "liquid",
      fragment: "liquid",
    },
    {
      attributes: ["position", "normal"],
      uniforms: ["world", "worldViewProjection", "worldPos", "sideColor", "topColor", "fillLevel", "wobble", "time", "rippleStrength"],
    },
  );
  liquidMaterial.backFaceCulling = false;
  liquidMaterial.zOffset = -1;

  let rootMesh;
  const defaultPP = new BABYLON.DefaultRenderingPipeline("default", true, scene, [camera]);
  defaultPP.fxaaEnabled = true;

  function loadGLB(fileName) {
    scene.transformNodes.forEach((tn) => {
      tn.dispose(false, true);
    });

    if (scene.metadata && scene.metadata.customUtilLayer) {
      scene.metadata.customUtilLayer.dispose();
    }

    BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", fileName).then((result) => {
      rootMesh = result.meshes[0];
      rootMesh.normalizeToUnitCube(true);
      rootMesh.position.y = 0.25;

      const fluidMeshesName = ["Fluid_2_8", "Fluid_3_9", "Fluid_4_10"];
      const glassMeshesName = ["Object_12", "Object_8", "Object_4"];

      rootMesh.getChildTransformNodes(false, (tn) => {
        if (fluidMeshesName.includes(tn.name)) tn.dispose();
      });

      rootMesh.getChildMeshes().forEach((mesh) => {
        if (mesh.getTotalVertices() > 0) {
          mesh.renderingGroupId = 2;
          if (glassMeshesName.includes(mesh.name)) {
            const liquid = mesh.clone(mesh.name + "_liquid");
            liquid.scaling.scaleInPlace(0.9);
            liquid.material = liquidMaterial;
            liquid.renderingGroupId = 1;
            liquid.isPickable = false;
            setupPhysicsAndGUI(rootMesh);
          }
        }
      });
    });
  }

  loadGLB("tri_flask.glb");

  //  물리 로직 및 GUI
  function setupPhysicsAndGUI(parentMesh) {
    const oldUI = scene.getTextureByName("MainUI");
    if (oldUI) oldUI.dispose();

    const randomHue = Math.random() * 360;

    // 측면: 진하고 깊은 색감 (채도 80%, 명도 60%)
    const generatedSideColor = BABYLON.Color3.FromHSV(randomHue, 0.8, 0.6);
    // 수면: 밝고 투명한 느낌 (채도 40%, 명도 90%)
    const generatedTopColor = BABYLON.Color3.FromHSV(randomHue, 0.4, 0.9);

    const bgColor3 = BABYLON.Color3.FromHSV(randomHue, 0.6, 0.3);
    scene.clearColor = new BABYLON.Color4(bgColor3.r, bgColor3.g, bgColor3.b, 1.0);

    const guiData = {
      fillLevel: 0.25,
      sideColor: generatedSideColor,
      topColor: generatedTopColor,
      stiffness: 0.15, // 탄성 계수
      damping: 0.93, // 감쇠 계수
      maxRipple: 0.15,
    };

    const ui = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("MainUI");
    const gizmoPanel = new BABYLON.GUI.StackPanel();
    gizmoPanel.width = "160px";
    gizmoPanel.top = "25px";
    // gizmoPanel.right = "25px";
    gizmoPanel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;
    gizmoPanel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
    ui.addControl(gizmoPanel);

    const glbPanel = new BABYLON.GUI.StackPanel();
    glbPanel.width = "160px";
    glbPanel.top = "25px";
    // glbPanel.left = "25px";
    glbPanel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    glbPanel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
    ui.addControl(glbPanel);

    // const addLabel = (text) => {
    //     const lbl = new BABYLON.GUI.TextBlock();
    //     lbl.text = text;
    //     lbl.height = "30px";
    //     lbl.color = "white";
    //     lbl.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    //     gizmoPanel.addControl(lbl);
    //     return lbl;
    // };

    // const addSlider = (label, min, max, val, prop) => {
    //     const lbl = addLabel(`${label}: ${val.toFixed(2)}`);
    //     const slider = new BABYLON.GUI.Slider();
    //     slider.minimum = min;
    //     slider.maximum = max;
    //     slider.value = val;
    //     slider.height = "20px";
    //     slider.width = "220px";
    //     slider.color = "green";
    //     slider.onValueChangedObservable.add((v) => { guiData[prop] = v; lbl.text = `${label}: ${v.toFixed(2)}`; });
    //     gizmoPanel.addControl(slider);
    // };

    // const addColorPicker = (label, prop) => {
    //     addLabel(label);
    //     const picker = new BABYLON.GUI.ColorPicker();
    //     picker.value = guiData[prop];
    //     picker.height = "120px";
    //     picker.width = "120px";
    //     picker.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    //     picker.onValueChangedObservable.add((v) => { guiData[prop] = v; });
    //     gizmoPanel.addControl(picker);
    // };

    // addSlider("Fill Level", 0.1, 0.75, guiData.fillLevel, "fillLevel");
    // addSlider("Damping (Viscosity)", 0.8, 0.99, guiData.damping, "damping");
    // addColorPicker("Side Liquid Color", "sideColor");
    // addColorPicker("Top Surface Color", "topColor");

    const utilLayer = new BABYLON.UtilityLayerRenderer(scene);
    scene.metadata = scene.metadata || {};
    scene.metadata.customUtilLayer = utilLayer;
    const posGizmo = new BABYLON.PositionGizmo(utilLayer);
    const rotGizmo = new BABYLON.RotationGizmo(utilLayer);

    const setGizmoMode = (mode) => {
      if (mode === "position") {
        posGizmo.attachedMesh = parentMesh;
        rotGizmo.attachedMesh = null;
        posBtn.background = "blue";
        rotBtn.background = "black";
      } else {
        posGizmo.attachedMesh = null;
        rotGizmo.attachedMesh = parentMesh;
        posBtn.background = "black";
        rotBtn.background = "blue";
      }
    };

    const posBtn = BABYLON.GUI.Button.CreateSimpleButton("posBtn", "Position");
    posBtn.width = "110px";
    posBtn.height = "30px";
    posBtn.color = "white";
    posBtn.onPointerClickObservable.add(() => setGizmoMode("position"));
    gizmoPanel.addControl(posBtn);

    const rotBtn = BABYLON.GUI.Button.CreateSimpleButton("rotBtn", "Rotation");
    rotBtn.width = "110px";
    rotBtn.height = "30px";
    rotBtn.color = "white";
    rotBtn.onPointerClickObservable.add(() => setGizmoMode("rotation"));
    gizmoPanel.addControl(rotBtn);

    setGizmoMode("position");

    const cylinderBtn = BABYLON.GUI.Button.CreateSimpleButton("cylinderBtn", "Cylinder");
    cylinderBtn.width = "110px";
    cylinderBtn.height = "30px";
    cylinderBtn.color = "black";
    cylinderBtn.background = "yellow";
    cylinderBtn.onPointerClickObservable.add(() => {
      loadGLB("cyl_flask.glb");
    });
    glbPanel.addControl(cylinderBtn);

    const roundBtn = BABYLON.GUI.Button.CreateSimpleButton("roundBtn", "Round");
    roundBtn.width = "110px";
    roundBtn.height = "30px";
    roundBtn.color = "black";
    roundBtn.background = "orange";
    roundBtn.onPointerClickObservable.add(() => {
      loadGLB("round_flask.glb");
    });
    glbPanel.addControl(roundBtn);

    const triBtn = BABYLON.GUI.Button.CreateSimpleButton("triBtn", "Erlenmeyer");
    triBtn.width = "110px";
    triBtn.height = "30px";
    triBtn.color = "black";
    triBtn.background = "Green";
    triBtn.onPointerClickObservable.add(() => {
      loadGLB("tri_flask.glb");
    });
    glbPanel.addControl(triBtn);

    // 물리 변수
    let lastPos = parentMesh.getAbsolutePosition().clone();
    let lastRot = parentMesh.rotationQuaternion ? parentMesh.rotationQuaternion.clone() : BABYLON.Quaternion.Identity();
    let wobblePos = new BABYLON.Vector2(0, 0);
    let wobbleVel = new BABYLON.Vector2(0, 0);

    let verticalBounce = 0;
    let verticalVel = 0;
    let time = 0;

    scene.onBeforeRenderObservable.add(() => {
      const dt = scene.getEngine().getDeltaTime() / 1000;
      if (dt <= 0) return;
      time += dt;

      const currentPos = parentMesh.getAbsolutePosition();
      const currentRot =
        parentMesh.rotationQuaternion || BABYLON.Quaternion.FromEulerAngles(parentMesh.rotation.x, parentMesh.rotation.y, parentMesh.rotation.z);

      const deltaRot = currentRot.multiply(BABYLON.Quaternion.Inverse(lastRot));
      const euler = deltaRot.toEulerAngles();

      // 1. 수평 가속도 (X, Z축 및 회전 관성) - 민감도 상향
      wobbleVel.x += ((currentPos.x - lastPos.x) / dt) * 0.15 + euler.z * 0.2;
      wobbleVel.y += ((currentPos.z - lastPos.z) / dt) * 0.15 + euler.x * 0.2;

      // 2. 수직 가속도 (Y축 위아래 반응) 핵심 추가
      const deltaY = ((currentPos.y - lastPos.y) / dt) * 0.4;
      verticalVel += deltaY * 0.5; // 위아래 이동량을 수직 벨로시티에 축적

      // 스프링-댐퍼 물리 연산 (수평)
      wobbleVel.x -= wobblePos.x * guiData.stiffness;
      wobbleVel.y -= wobblePos.y * guiData.stiffness;
      wobbleVel.x *= guiData.damping;
      wobbleVel.y *= guiData.damping;
      wobblePos.x += wobbleVel.x * dt;
      wobblePos.y += wobbleVel.y * dt;

      // 스프링-댐퍼 물리 연산 (수직 바운스)
      verticalVel -= verticalBounce * guiData.stiffness * 2.0;
      verticalVel *= guiData.damping;
      verticalBounce += verticalVel * dt;

      // 3. 쉐이더 유니폼 업데이트
      liquidMaterial.setVector2("wobble", wobblePos);

      // 리플 강도에 수직 바운스 강도를 합산하여 위아래 흔들림 시 출렁임 극대화
      const totalEnergy = wobblePos.length() + Math.abs(verticalBounce);
      liquidMaterial.setFloat("rippleStrength", Math.min(totalEnergy * 0.5, guiData.maxRipple));

      // 수직 바운스를 fillLevel에 미세하게 더해 액체가 위아래로 꿀렁이는 효과 부여
      liquidMaterial.setFloat("fillLevel", guiData.fillLevel + verticalBounce * 0.1);

      liquidMaterial.setVector3("worldPos", currentPos);
      liquidMaterial.setFloat("time", time);
      liquidMaterial.setColor3("sideColor", guiData.sideColor);
      liquidMaterial.setColor3("topColor", guiData.topColor);

      lastPos.copyFrom(currentPos);
      lastRot.copyFrom(currentRot);
    });
  }

  return scene;
}
